import sys

def parse_deltas(line: str):
    line = line.strip()
    if not line:
        return []
    parts = line.split(',')
    deltas = []
    for p in parts:
        p = p.strip()
        if p:
            deltas.append(int(p))
    return deltas

def solve():
    line = sys.stdin.readline()
    deltas = parse_deltas(line)

    # Part 2: find the first frequency reached twice
    freq = 0
    seen = {0}

    i = 0
    n = len(deltas)
    while True:
        freq += deltas[i]
        if freq in seen:
            print(freq)
            return
        seen.add(freq)
        i += 1
        if i == n:
            i = 0

if __name__ == "__main__":
    solve()

