from collections import Counter

def solve():
    count_exactly_two = 0
    count_exactly_three = 0

    for line in sys.stdin:
        s = line.strip()
        if not s:
            continue

        freq = Counter(s)
        has_two = 2 in freq.values()
        has_three = 3 in freq.values()

        if has_two:
            count_exactly_two += 1
        if has_three:
            count_exactly_three += 1

    print(count_exactly_two * count_exactly_three)

if __name__ == "__main__":
    solve()

