import sys

def solve():
    ids = [line.strip() for line in sys.stdin if line.strip() != ""]
    if not ids:
        return

    L = len(ids[0])
    seen = {}  # variant -> original id

    for s in ids:
        # If input lines can vary in length, only compare within the first line's length
        # (standard puzzle guarantees equal length).
        if len(s) != L:
            continue
        for i in range(L):
            variant = s[:i] + s[i+1:]
            if variant in seen:
                sys.stdout.write(variant + "\n")
                return
            seen[variant] = s

    # If no pair found (shouldn't happen for valid puzzle inputs)
    sys.stdout.write("\n")

if __name__ == "__main__":
    solve()

