import sys
import re

def solve(lines):
    claims = []
    max_x2 = 0
    max_y2 = 0

    # Parse input lines
    pat = re.compile(r"#(\d+)\s*@\s*(\d+),(\d+):\s*(\d+)x(\d+)")
    for line in lines:
        line = line.strip()
        if not line:
            continue
        m = pat.match(line)
        if not m:
            continue
        cid = int(m.group(1))
        left = int(m.group(2))
        top = int(m.group(3))
        w = int(m.group(4))
        h = int(m.group(5))

        x1 = left
        x2 = left + w
        y1 = top
        y2 = top + h

        claims.append((cid, x1, x2, y1, y2))
        if x2 > max_x2:
            max_x2 = x2
        if y2 > max_y2:
            max_y2 = y2

    if not claims:
        return ""

    W = max_x2
    H = max_y2

    # 2D difference array: diff[x][y]
    diff = [[0] * (H + 1) for _ in range(W + 1)]

    # Apply rectangle updates
    for _, x1, x2, y1, y2 in claims:
        diff[x1][y1] += 1
        diff[x2][y1] -= 1
        diff[x1][y2] -= 1
        diff[x2][y2] += 1

    # Reconstruct coverage counts via 2D prefix sums
    cover = [[0] * H for _ in range(W)]
    for x in range(W):
        for y in range(H):
            v = diff[x][y]
            if x > 0:
                v += cover[x - 1][y]
            if y > 0:
                v += cover[x][y - 1]
            if x > 0 and y > 0:
                v -= cover[x - 1][y - 1]
            cover[x][y] = v

    # Part 2: find the only intact claim
    # Map claim id -> intact status
    intact = {cid: True for cid, _, _, _, _ in claims}

    for cid, x1, x2, y1, y2 in claims:
        ok = True
        for x in range(x1, x2):
            # Early exit if already found overlap
            if not ok:
                break
            row = cover[x]
            for y in range(y1, y2):
                if row[y] >= 2:
                    ok = False
                    break
        intact[cid] = ok

    # Output the intact claim ID
    for cid, _, _, _, _ in claims:
        if intact.get(cid, False):
            return str(cid)
    return ""

def main():
    lines = sys.stdin.read().splitlines()
    out = solve(lines)
    if out is not None:
        sys.stdout.write(out)

if __name__ == "__main__":
    main()

