import sys
import re

def solve(lines):
    records = []
    guard_re = re.compile(r"Guard #(\d+) begins shift")
    ts_re = re.compile(r"\[(\d+)-(\d+)-(\d+) (\d+):(\d+)\]")

    for line in lines:
        line = line.strip()
        if not line:
            continue
        m = ts_re.search(line)
        if not m:
            continue
        year, month, day, hour, minute = map(int, m.groups())
        ts = (year, month, day, hour, minute)

        if "falls asleep" in line:
            records.append((ts, "SLEEP", None))
        elif "wakes up" in line:
            records.append((ts, "WAKE", None))
        else:
            gm = guard_re.search(line)
            if gm:
                guard_id = int(gm.group(1))
                records.append((ts, "BEGIN", guard_id))

    records.sort(key=lambda x: x[0])

    counts = {}  # guard_id -> [60 minute counts]
    current_guard = None
    sleep_start_minute = None

    for ts, event, guard_id in records:
        minute = ts[4]  # minute within 00-59
        if event == "BEGIN":
            current_guard = guard_id
            if current_guard not in counts:
                counts[current_guard] = [0] * 60
        elif event == "SLEEP":
            sleep_start_minute = minute
        elif event == "WAKE":
            wake_minute = minute
            # asleep on [sleep_start_minute, wake_minute)
            for m in range(sleep_start_minute, wake_minute):
                counts[current_guard][m] += 1

    best_guard = None
    best_minute = None
    best_count = -1

    for gid, arr in counts.items():
        for m in range(60):
            c = arr[m]
            if c > best_count:
                best_count = c
                best_guard = gid
                best_minute = m

    return str(best_guard * best_minute)

if __name__ == "__main__":
    input_lines = sys.stdin.read().splitlines()
    print(solve(input_lines))

