import sys

def fully_react_length(poly: str) -> int:
    stack = []
    for ch in poly.strip():
        if stack:
            top = stack[-1]
            # React if same type ignoring polarity and opposite polarity (one lower, one upper)
            if top != ch and top.lower() == ch.lower() and (top.islower() != ch.islower()):
                stack.pop()
            else:
                stack.append(ch)
        else:
            stack.append(ch)
    return len(stack)

def main():
    poly = sys.stdin.readline()
    if poly is None:
        print(0)
        return
    poly = poly.rstrip("\n")
    print(fully_react_length(poly))

if __name__ == "__main__":
    main()

