import sys

def fully_react_length(s: str, remove_type: str | None = None) -> int:
    stack = []
    for ch in s:
        if remove_type is not None and ch.lower() == remove_type:
            continue
        if stack and stack[-1] != ch and stack[-1].lower() == ch.lower():
            stack.pop()
        else:
            stack.append(ch)
    return len(stack)

def solve() -> None:
    s = sys.stdin.readline().strip()
    if not s:
        print(0)
        return

    best = 10**18
    for t in "abcdefghijklmnopqrstuvwxyz":
        best = min(best, fully_react_length(s, t))

    print(best)

if __name__ == "__main__":
    solve()

