import sys
import heapq
import re

def solve(data: str) -> str:
    graph = {}
    indegree = {}
    steps = set()

    line_re = re.compile(r"Step ([A-Z]) must be finished before step ([A-Z]) can begin\.")

    for line in data.splitlines():
        line = line.strip()
        if not line:
            continue
        m = line_re.match(line)
        if not m:
            continue
        u, v = m.group(1), m.group(2)
        steps.add(u)
        steps.add(v)

        if u not in graph:
            graph[u] = []
        graph[u].append(v)

        indegree[v] = indegree.get(v, 0) + 1
        indegree.setdefault(u, indegree.get(u, 0))

    # Ensure all steps exist in graph/indegree structures
    for s in steps:
        graph.setdefault(s, [])
        indegree.setdefault(s, 0)

    # Min-heap of available steps (indegree == 0)
    pq = [s for s in steps if indegree[s] == 0]
    heapq.heapify(pq)

    order = []
    while pq:
        u = heapq.heappop(pq)
        order.append(u)
        for v in graph[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                heapq.heappush(pq, v)

    # If cycle exists, order will be incomplete; still output what we have.
    return "".join(order)

if __name__ == "__main__":
    data = sys.stdin.read()
    sys.stdout.write(solve(data) + "\n")

