import sys

def solve() -> None:
    lines = [line.strip() for line in sys.stdin if line.strip()]
    if not lines:
        return

    # Parse initial state
    init_line = lines[0]
    initial = init_line.split(":")[1].strip()
    plants = {i for i, ch in enumerate(initial) if ch == '#'}

    # Parse rules: pattern (5 chars) -> result char
    rule = {}
    for line in lines[1:]:
        left, right = line.split("=>")
        pattern = left.strip()
        result = right.strip()
        rule[pattern] = result

    # Simulate 20 generations
    for _ in range(20):
        if not plants:
            break

        min_i = min(plants)
        max_i = max(plants)

        next_plants = set()
        # Only pots within min-2 .. max+2 can change
        for p in range(min_i - 2, max_i + 3):
            pattern_chars = []
            for k in (-2, -1, 0, 1, 2):
                pattern_chars.append('#' if (p + k) in plants else '.')
            pattern = ''.join(pattern_chars)

            if rule.get(pattern, '.') == '#':
                next_plants.add(p)

        plants = next_plants

    print(sum(plants))

if __name__ == "__main__":
    solve()

