import sys

def parse_input(lines):
    initial = ""
    rules = set()

    for line in lines:
        line = line.strip()
        if not line:
            continue
        if line.startswith("initial state:"):
            initial = line.split(":")[1].strip()
        else:
            pat, out = line.split("=>")
            pat = pat.strip()
            out = out.strip()
            if out == "#":
                rules.add(pat)

    plants = set()
    for i, ch in enumerate(initial):
        if ch == "#":
            plants.add(i)  # pot index 0 corresponds to first char

    return plants, rules

def step(plants, produces):
    if not plants:
        return set()

    min_p = min(plants)
    max_p = max(plants)

    next_plants = set()
    # Only pots within [min-2, max+2] can possibly change
    for x in range(min_p - 2, max_p + 3):
        # Build neighborhood pattern for [x-2, x-1, x, x+1, x+2]
        pat = []
        for d in (-2, -1, 0, 1, 2):
            pat.append('#' if (x + d) in plants else '.')
        if ''.join(pat) in produces:
            next_plants.add(x)
    return next_plants

def signature(plants):
    if not plants:
        return ()
    min_p = min(plants)
    norm = tuple(sorted(p - min_p for p in plants))
    return norm

def sum_plants(plants):
    return sum(plants)

def solve(target, plants, produces):
    seen = {}  # signature -> (gen, min_p)
    gen = 0

    while gen < target:
        sig = signature(plants)
        if sig in seen:
            prev_gen, prev_min = seen[sig]
            cycle_len = gen - prev_gen
            drift = min(plants) - prev_min  # how much min shifts per cycle

            remaining = target - prev_gen
            k = remaining // cycle_len
            # We want to jump to generation prev_gen + k*cycle_len
            gen_after = prev_gen + k * cycle_len

            # Apply k cycles shift to current absolute positions based on normalized signature
            if sig:
                norm_positions = sig
                new_min = prev_min + k * drift
                plants = set(p + new_min for p in norm_positions)
            else:
                plants = set()

            gen = gen_after
            if gen == target:
                break
            # Continue with remainder simulation
            continue

        # Record current state
        if sig:
            seen[sig] = (gen, min(plants))
        else:
            seen[sig] = (gen, 0)

        plants = step(plants, produces)
        gen += 1

    return sum_plants(plants)

