            nx, ny = x + dx, y + dy

            # Collision check
            if (nx, ny) in pos_to_cart:
                sys.stdout.write(f"{nx},{ny}")
                return

            # Move cart
            carts[cid][0] = nx
            carts[cid][1] = ny

            track = grid[ny][nx]
            if track == '/':
                carts[cid][2] = curve_slash[d]
            elif track == '\\':
                carts[cid][2] = curve_back[d]
            elif track == '+':
                # Apply turn based on turn_state
                if turn_state == 0:  # left
                    carts[cid][2] = left_turn[d]
