                    carts[cid][2] = d
                else:  # right
                    carts[cid][2] = right_turn[d]
                carts[cid][3] = (turn_state + 1) % 3
            else:
                # '-' or '|' => direction unchanged
                carts[cid][2] = d

            # Insert new position
            pos_to_cart[(nx, ny)] = cid

