import sys

def solve():
    lines = [line.rstrip("\n") for line in sys.stdin.readlines()]
    if not lines:
        return

    H = len(lines)
    W = max(len(s) for s in lines)

    grid = [list(s.ljust(W)) for s in lines]

    # Direction vectors and mapping
    DIRS = {
        'up': (0, -1),
        'down': (0, 1),
        'left': (-1, 0),
        'right': (1, 0),
    }
    VEC_TO_DIR = {v: k for k, v in DIRS.items()}

    def turn_left(dir_name):
        dx, dy = DIRS[dir_name]
        # left turn: (dx,dy) -> (-dy, dx)
        ndx, ndy = -dy, dx
        return VEC_TO_DIR[(ndx, ndy)]

    def turn_right(dir_name):
        dx, dy = DIRS[dir_name]
        # right turn: (dx,dy) -> (dy, -dx)
        ndx, ndy = dy, -dx
        return VEC_TO_DIR[(ndx, ndy)]

    def apply_curve(dir_name, track_ch):
        # Curves connect perpendicular pieces; update direction based on destination track.
        if track_ch == '/':
            # up->right, down->left, left->down, right->up
            mapping = {'up': 'right', 'down': 'left', 'left': 'down', 'right': 'up'}
            return mapping[dir_name]
        else:  # '\\'
            # up->left, down->right, left->up, right->down
            mapping = {'up': 'left', 'down': 'right', 'left': 'up', 'right': 'down'}
            return mapping[dir_name]

    carts = []
    pos_to_cart = {}  # (x,y) -> cart_id

    cart_glyphs = {'^': 'up', 'v': 'down', '<': 'left', '>': 'right'}
    for y in range(H):
        for x in range(W):
            ch = grid[y][x]
            if ch in cart_glyphs:
                dir_name = cart_glyphs[ch]
                cart_id = len(carts)
                carts.append({
                    'x': x,
                    'y': y,
                    'dir': dir_name,
                    'turn_state': 0,  # 0=left,1=straight,2=right
                    'alive': True
                })
                pos_to_cart[(x, y)] = cart_id
                # Normalize underlying track
                if ch in '^v':
                    grid[y][x] = '|'
                else:
                    grid[y][x] = '-'

    # Simulate until one cart remains
    while True:
        alive_ids = [i for i, c in enumerate(carts) if c['alive']]
        if len(alive_ids) == 1:
            c = carts[alive_ids[0]]
            print(f"{c['x']},{c['y']}")
            return

        # Process carts in required order: top-to-bottom, then left-to-right
        alive_ids.sort(key=lambda i: (carts[i]['y'], carts[i]['x']))

        for cid in alive_ids:
            cart = carts[cid]
            if not cart['alive']:
                continue

            x, y = cart['x'], cart['y']
            dx, dy = DIRS[cart['dir']]
            nx, ny = x + dx, y + dy

            other = pos_to_cart.get((nx, ny))
            if other is None:
                # Move cart
                del pos_to_cart[(x, y)]
                cart['x'], cart['y'] = nx, ny
                pos_to_cart[(nx, ny)] = cid

                track_ch = grid[ny][nx]
                if track_ch == '/':
                    cart['dir'] = apply_curve(cart['dir'], '/')
                elif track_ch == '\\':
                    cart['dir'] = apply_curve(cart['dir'], '\\')
                elif track_ch == '+':
                    ts = cart['turn_state']
                    if ts == 0:
                        cart['dir'] = turn_left(cart['dir'])
                    elif ts == 2:
                        cart['dir'] = turn_right(cart['dir'])
                    # ts==1 => straight, no change
                    cart['turn_state'] = (ts + 1) % 3
                # else: '-' or '|' => direction unchanged
            else:
                # Collision: remove both carts immediately
                cart['alive'] = False
                carts[other]['alive'] = False
                # Remove positions from occupancy map
                # Moving cart's old position is still in pos_to_cart
                if (x, y) in pos_to_cart:
                    del pos_to_cart[(x, y)]
                if (nx, ny) in pos_to_cart:
                    del pos_to_cart[(nx, ny)]
                # Do not insert moving cart into occupancy map

        # Loop continues; stop condition checked at top

if __name__ == "__main__":
    solve()

