import sys

def solve(depth, target_x, target_y):
    MOD = 20183
    erosion = [[0] * (target_x + 1) for _ in range(target_y + 1)]
    risk_sum = 0

    for y in range(target_y + 1):
        for x in range(target_x + 1):
            if x == 0 and y == 0:
                gi = 0
            elif x == target_x and y == target_y:
                gi = 0
            elif y == 0:
                gi = x * 16807
            elif x == 0:
                gi = y * 48271
            else:
                gi = erosion[y][x - 1] * erosion[y - 1][x]

            el = (gi + depth) % MOD
            erosion[y][x] = el
            risk_sum += el % 3

    return risk_sum

