import sys
import re

def solve(data: str) -> str:
    bots = []
    # Example line: pos=<0,0,0>, r=4
    pat = re.compile(r'pos=<\s*(-?\d+)\s*,\s*(-?\d+)\s*,\s*(-?\d+)\s*>\s*,\s*r=\s*(-?\d+)\s*$')

    for line in data.splitlines():
        line = line.strip()
        if not line:
            continue
        m = pat.match(line)
        if not m:
            continue
        x, y, z, r = map(int, m.groups())
        bots.append((x, y, z, r))

    if not bots:
        return "0"

    # Step 2: find maximum radius
    max_r = max(r for _, _, _, r in bots)
    candidates = [(x, y, z) for x, y, z, r in bots if r == max_r]

    # Step 5: robust tie handling - compute max count among max-radius candidates
    best_count = 0
    for bx, by, bz in candidates:
        cnt = 0
        for x, y, z, r in bots:
            dist = abs(x - bx) + abs(y - by) + abs(z - bz)
            if dist <= max_r:
                cnt += 1
        if cnt > best_count:
            best_count = cnt

    return str(best_count)

def main():
    data = sys.stdin.read()
    print(solve(data))

if __name__ == "__main__":
    main()

