import sys

def run_intcode(program, noun, verb):
    mem = program.copy()
    mem[1] = noun
    mem[2] = verb

    ip = 0
    while True:
        opcode = mem[ip]
        if opcode == 99:
            return mem[0]
        if opcode == 1 or opcode == 2:
            a = mem[ip + 1]
            b = mem[ip + 2]
            out = mem[ip + 3]
            if opcode == 1:
                mem[out] = mem[a] + mem[b]
            else:
                mem[out] = mem[a] * mem[b]
            ip += 4
        else:
            raise ValueError(f"Unknown opcode {opcode} at position {ip}")

def main():
    data = sys.stdin.read().strip()
    if not data:
        return
    program = [int(x) for x in data.replace('\n', '').split(',') if x.strip() != '']

    target = 19690720
    for noun in range(100):
        for verb in range(100):
            if run_intcode(program, noun, verb) == target:
                print(100 * noun + verb)
                return

if __name__ == "__main__":
    main()

