import sys

def parse_wire(line: str):
    line = line.strip()
    if not line:
        return []
    parts = line.split(',')
    instr = []
    for p in parts:
        d = p[0]
        n = int(p[1:])
        instr.append((d, n))
    return instr

def solve():
    lines = [ln.strip() for ln in sys.stdin.read().splitlines() if ln.strip() != ""]
    if len(lines) < 2:
        return
    wire_a = parse_wire(lines[0])
    wire_b = parse_wire(lines[1])

    # visitedA maps position -> first step count when wire A first reaches it
    visitedA = {}
    x = y = 0
    steps = 0
    for d, n in wire_a:
        for _ in range(n):
            if d == 'R':
                x += 1
            elif d == 'L':
                x -= 1
            elif d == 'U':
                y += 1
            else:  # 'D'
                y -= 1
            steps += 1
            pos = (x, y)
            if pos not in visitedA:
                visitedA[pos] = steps

    bestCombinedSteps = float('inf')

    x = y = 0
    steps = 0
    for d, n in wire_b:
        for _ in range(n):
            if d == 'R':
                x += 1
            elif d == 'L':
                x -= 1
            elif d == 'U':
                y += 1
            else:  # 'D'
                y -= 1
            steps += 1
            pos = (x, y)
            if pos in visitedA:
                combined = steps + visitedA[pos]
                if combined < bestCombinedSteps:
                    bestCombinedSteps = combined

    if bestCombinedSteps == float('inf'):
        bestCombinedSteps = 0
    print(int(bestCombinedSteps))

if __name__ == "__main__":
    solve()

