import sys

def count_passwords(low: int, high: int) -> int:
    # Backtrack to generate all non-decreasing 6-digit sequences
    # and count those within [low, high] that have at least one adjacent equal pair.
    digits = [0] * 6
    ans = 0

    def dfs(pos: int, prev_digit: int, has_adjacent_pair: bool):
        nonlocal ans
        if pos == 6:
            x = 0
            for d in digits:
                x = x * 10 + d
            if low <= x <= high and has_adjacent_pair:
                ans += 1
            return

        for d in range(prev_digit, 10):
            digits[pos] = d
            dfs(pos + 1, d, has_adjacent_pair or (pos > 0 and d == prev_digit))

    dfs(0, 0, False)
    return ans

def main():
    s = sys.stdin.readline().strip()
    if not s:
        return
    a, b = s.split('-')
    low = int(a)
    high = int(b)
    print(count_passwords(low, high))

if __name__ == "__main__":
    main()

