import sys
from functools import lru_cache

def count_up_to(x: int) -> int:
    if x < 0:
        return 0

    # Represent x as exactly 6 digits (passwords are 6-digit numbers)
    digits = list(map(int, f"{x:06d}"))

    @lru_cache(maxsize=None)
    def dp(pos: int, prev: int, run_len: int, has_double: int, tight: int, started: int) -> int:
        if pos == 6:
            if started == 0:
                return 0
            # Finalize the last run
            if run_len == 2:
                return 1 if has_double == 1 else 1
            return 1 if has_double == 1 else 0

        limit = digits[pos] if tight else 9
        total = 0

        for d in range(limit + 1):
            tight_next = 1 if (tight and d == limit) else 0  # careful: limit is digits[pos] when tight
            # Fix tight_next computation properly:
            if tight:
                tight_next = 1 if d == digits[pos] else 0
            else:
                tight_next = 0

            if started == 0:
                if d == 0:
                    # Still not started; no run yet
                    total += dp(pos + 1, 0, 0, has_double, tight_next, 0)
                else:
                    # Start first run with digit d
                    total += dp(pos + 1, d, 1, has_double, tight_next, 1)
            else:
                # Non-decreasing constraint
                if d < prev:
                    continue

                if d == prev:
                    # Extend current run
                    total += dp(pos + 1, prev, run_len + 1, has_double, tight_next, 1)
                else:
                    # Close previous run; check if it was exactly length 2
                    new_has_double = has_double
                    if run_len == 2:
                        new_has_double = 1
                    total += dp(pos + 1, d, 1, new_has_double, tight_next, 1)

        return total

    # Note: has_double is 0/1; run_len can be 0..6; prev is 0..9
    return dp(0, 0, 0, 0, 1, 0)

def solve():
    s = sys.stdin.readline().strip()
    if not s:
        return
    left, right = s.split('-')
    L = int(left)
    R = int(right)
    ans = count_up_to(R) - count_up_to(L - 1)
    sys.stdout.write(str(ans))

if __name__ == "__main__":
    solve()

